// Replays streams generated by scripts/gen_demo_streams.py into the same
// component the example tests use. No typing is modelled here.
(function () {
  "use strict";

  var DATA = window.DEMO_STREAMS;
  var AC = window.Autocomplete;
  var QUIET_MS = 1500;
  var SVG_NS = "http://www.w3.org/2000/svg";
  var FAILING = [1, 7, 8, 10, 12];
  var reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  var el = {
    play: document.getElementById("play"),
    replay: document.getElementById("replay"),
    seed: document.getElementById("seed"),
    fixed: document.getElementById("fixed"),
    seedNote: document.getElementById("seed-note"),
    left: document.getElementById("left"),
    right: document.getElementById("right"),
    leftVerdict: document.getElementById("left-verdict"),
    rightVerdict: document.getElementById("right-verdict"),
    rightTitle: document.getElementById("right-title"),
    how: document.querySelector("#right-title + .how code"),
    keys: document.getElementById("keys"),
    keyboard: document.getElementById("keyboard"),
    timeline: document.getElementById("timeline"),
    timelineSeed: document.getElementById("timeline-seed"),
  };

  var run = null;

  function streamFor(seed) {
    return DATA.streams.filter(function (s) { return s.seed === seed; })[0];
  }

  // ---- seed picker ----
  DATA.streams.forEach(function (s) {
    var opt = document.createElement("option");
    opt.value = String(s.seed);
    opt.textContent = "seed " + s.seed;
    el.seed.appendChild(opt);
  });
  el.seedNote.textContent =
    "Seeds " + FAILING.slice(0, -1).join(", ") + " and " + FAILING[FAILING.length - 1] +
    " fail in the example's test suite; seed 0 passes. Each is a stream from the Python engine.";

  // ---- keyboard ----
  var ROWS = [
    { y: 0, x: 0, keys: "qwertyuiop".split("") },
    { y: 1, x: 0.5, keys: "asdfghjkl".split("") },
    { y: 2, x: 1, keys: "zxcvbnm".split("") },
  ];
  var KEY = 40, GAP = 4;
  var keyNodes = {};

  function svg(tag, attrs, parent) {
    var n = document.createElementNS(SVG_NS, tag);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(n);
    return n;
  }

  function addKey(id, label, x, y, w) {
    var g = svg("g", { class: "k" }, el.keyboard);
    svg("rect", { x: x, y: y, width: w, height: KEY, rx: 5 }, g);
    var t = svg("text", { x: x + w / 2, y: y + KEY / 2 }, g);
    t.textContent = label;
    keyNodes[id] = g;
  }

  function buildKeyboard() {
    ROWS.forEach(function (row) {
      row.keys.forEach(function (k, i) {
        addKey(k, k.toUpperCase(), (row.x + i) * (KEY + GAP), row.y * (KEY + GAP), KEY);
      });
    });
    var w = 10 * (KEY + GAP);
    addKey("backspace", "⌫", w, 0, 64);
    addKey("arrowleft", "←", 8 * (KEY + GAP) + 20, 3 * (KEY + GAP), KEY);
    addKey("arrowright", "→", 9 * (KEY + GAP) + 20, 3 * (KEY + GAP), KEY);
    addKey(" ", "space", 2.5 * (KEY + GAP), 3 * (KEY + GAP), 5 * (KEY + GAP) - GAP);
    el.keyboard.setAttribute("viewBox", "0 0 " + (w + 64) + " " + (4 * (KEY + GAP) - GAP));
  }
  buildKeyboard();

  function keyId(key) {
    return key.length === 1 ? key.toLowerCase() : key;
  }

  function showKey(e, down) {
    if (reducedMotion.matches) return;
    var node = keyNodes[keyId(e.key)];
    if (!node) return;
    node.classList.toggle("down", down);
    node.classList.toggle("err", down && e.is_error);
    node.classList.toggle("fix", down && e.is_correction && !e.is_error);
  }

  function clearKeyboard() {
    Object.keys(keyNodes).forEach(function (k) { keyNodes[k].setAttribute("class", "k"); });
  }

  var KEY_LABEL = { backspace: "⌫", arrowleft: "←", arrowright: "→", " ": "␣" };

  function addKeyChip(e) {
    var li = document.createElement("li");
    li.textContent = KEY_LABEL[e.key] || e.key;
    if (e.is_error) li.className = "err";
    else if (e.is_correction) li.className = "fix";
    var name = e.key.length === 1 ? e.key : e.key.replace("arrow", "arrow ");
    li.setAttribute("aria-label", name + (e.is_error ? " (typo)" : e.is_correction ? " (correction)" : ""));
    el.keys.appendChild(li);
  }

  // ---- real DOM events into the input ----
  var DOM_KEY = { backspace: "Backspace", arrowleft: "ArrowLeft", arrowright: "ArrowRight", "\n": "Enter" };

  function dispatchKey(input, e) {
    var type = e.action === "keydown" ? "keydown" : "keyup";
    var domKey = DOM_KEY[e.key] || e.key;
    input.dispatchEvent(new KeyboardEvent(type, { key: domKey, bubbles: true, cancelable: true }));
    if (type !== "keydown") return;

    var s = input.selectionStart, end = input.selectionEnd;
    if (e.key === "backspace") {
      if (s === end && s === 0) return;
      input.setRangeText("", s === end ? s - 1 : s, end, "end");
      input.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "deleteContentBackward" }));
    } else if (e.key === "arrowleft") {
      var l = Math.max(0, s - 1);
      input.setSelectionRange(l, l);
    } else if (e.key === "arrowright") {
      var r = Math.min(input.value.length, end + 1);
      input.setSelectionRange(r, r);
    } else if (e.key.length === 1) {
      input.setRangeText(e.key, s, end, "end");
      input.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertText", data: e.key }));
    }
  }

  function fill(input, text) {
    input.value = text;
    input.setSelectionRange(text.length, text.length);
    input.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: text }));
  }

  // ---- timeline ----
  var TL = { w: 1000, left: 8, right: 8, top: 26, lane: 22 };

  function Timeline(totalMs) {
    this.total = totalMs;
    this.lanes = 0;
    this.bars = {};
    el.timeline.replaceChildren();
    this.root = el.timeline;
    this.axis = svg("g", { class: "axis" }, this.root);
    this.ticks = svg("g", {}, this.root);
    this.reqs = svg("g", {}, this.root);
    this.resize(1);
  }
  Timeline.prototype.x = function (t) {
    return TL.left + (Math.min(t, this.total) / this.total) * (TL.w - TL.left - TL.right);
  };
  Timeline.prototype.resize = function (lanes) {
    var h = TL.top + 14 + lanes * TL.lane + 22;
    this.root.setAttribute("viewBox", "0 0 " + TL.w + " " + h);
    this.axis.replaceChildren();
    var y = h - 18;
    svg("line", { x1: TL.left, x2: TL.w - TL.right, y1: y, y2: y }, this.axis);
    for (var s = 0; s * 1000 <= this.total; s++) {
      var x = this.x(s * 1000);
      svg("line", { x1: x, x2: x, y1: y, y2: y + 4 }, this.axis);
      var t = svg("text", { x: x, y: y + 15, "text-anchor": s === 0 ? "start" : "middle" }, this.axis);
      t.textContent = s + " s";
    }
  };
  Timeline.prototype.key = function (t, e) {
    var x = this.x(t);
    var cls = "tick" + (e.is_error ? " err" : e.is_correction ? " fix" : "");
    svg("line", { class: cls, x1: x, x2: x, y1: 4, y2: TL.top }, this.ticks);
  };
  Timeline.prototype.endOfTyping = function (t) {
    var x = this.x(t);
    svg("line", { class: "end", x1: x, x2: x, y1: 0, y2: 2000 }, this.ticks);
    var label = svg("text", { class: "label", x: x + 4, y: 12 }, this.ticks);
    label.textContent = "last key";
  };
  Timeline.prototype.request = function (t, ev) {
    var lane = this.lanes++;
    this.resize(this.lanes);
    var y = TL.top + 10 + lane * TL.lane;
    var x0 = this.x(t), x1 = this.x(t + ev.latency);
    var rect = svg("rect", { class: "bar", x: x0, y: y, width: Math.max(2, x1 - x0), height: 14, rx: 2 }, this.reqs);
    var label = svg("text", { class: "label", x: x1 + 5, y: y + 11 }, this.reqs);
    label.textContent = '"' + ev.query + '" ' + ev.latency + " ms";
    if (x1 > TL.w - 190) {
      label.setAttribute("x", x0 - 5);
      label.setAttribute("text-anchor", "end");
    }
    this.bars[ev.id] = { rect: rect, label: label };
  };
  Timeline.prototype.mark = function (id, cls) {
    var b = this.bars[id];
    if (!b) return;
    b.rect.setAttribute("class", "bar done " + cls);
    if (cls === "stale" || cls === "ok") b.label.setAttribute("class", "label strong");
  };

  // ---- a run ----
  function setVerdict(node, cls, text) {
    node.className = "verdict " + cls;
    node.textContent = text;
  }

  function resetPanel(root) {
    var input = root.querySelector("[data-role=input]");
    input.value = "";
    root.querySelector("[data-role=query]").textContent = "";
    root.querySelector("[data-role=list]").replaceChildren();
    return input;
  }

  function stop() {
    if (!run) return;
    run.timers.forEach(clearTimeout);
    run.components.forEach(function (c) { c.destroy(); });
    clearKeyboard();
    run = null;
  }

  function start() {
    stop();
    var seed = Number(el.seed.value);
    var stream = streamFor(seed);
    var fixed = el.fixed.checked;
    var my = { timers: [], components: [], seed: seed };
    run = my;

    el.rightTitle.textContent = "humaninput, seed " + seed;
    el.how.textContent = 'type_into(..., profile="' + DATA.profile + '", seed=' + seed + ")";
    el.timelineSeed.textContent = String(seed);
    el.keys.replaceChildren();
    document.body.dataset.running = "true";
    el.replay.disabled = false;

    var leftInput = resetPanel(el.left);
    var rightInput = resetPanel(el.right);
    var t0 = performance.now();
    var lastKeyMs = 0;
    stream.events.forEach(function (e) { if (e.action === "keydown") lastKeyMs = Math.max(lastKeyMs, e.t_ms); });
    var tl = new Timeline(lastKeyMs + QUIET_MS);
    var latestRendered = null;

    my.components.push(AC.create(el.left, { fixed: fixed }));
    my.components.push(AC.create(el.right, {
      fixed: fixed,
      onEvent: function (ev) {
        if (run !== my) return;
        var t = ev.t - t0;
        if (ev.type === "request") tl.request(t, ev);
        else if (ev.type === "ignored") tl.mark(ev.id, "ign");
        else if (ev.type === "render") {
          latestRendered = ev;
          tl.mark(ev.id, "");
        }
      },
    }));

    setVerdict(el.leftVerdict, "wait", "Typing…");
    setVerdict(el.rightVerdict, "wait", "Typing…");
    fill(leftInput, DATA.text);
    setVerdict(el.leftVerdict, "wait", "Waiting 1.5 s for results, like the test does…");

    function at(ms, fn) {
      my.timers.push(setTimeout(function () { if (run === my) fn(); }, Math.max(0, ms - (performance.now() - t0))));
    }

    at(QUIET_MS, function () { check(el.left, el.leftVerdict, "Test passes"); });

    stream.events.forEach(function (e) {
      at(e.t_ms, function () {
        dispatchKey(rightInput, e);
        showKey(e, e.action === "keydown");
        if (e.action === "keydown") {
          addKeyChip(e);
          tl.key(e.t_ms, e);
        }
      });
    });

    at(lastKeyMs, function () {
      tl.endOfTyping(lastKeyMs);
      setVerdict(el.rightVerdict, "wait", "Waiting 1.5 s for results, like the test does…");
    });

    at(stream.duration_ms + 1, clearKeyboard);

    at(lastKeyMs + QUIET_MS, function () {
      check(el.right, el.rightVerdict, "Test passes");
      if (latestRendered) tl.mark(latestRendered.id, latestRendered.query === rightInput.value ? "ok" : "stale");
      delete document.body.dataset.running;
      run.components.forEach(function (c) { c.destroy(); });
      run = null;
    });
  }

  function check(root, verdictNode, passText) {
    var typed = root.querySelector("[data-role=input]").value;
    var shown = root.querySelector("[data-role=query]").textContent;
    if (shown === typed) setVerdict(verdictNode, "ok", "✓ " + passText + ": shows results for " + typed);
    else setVerdict(verdictNode, "bad", "✗ Shows results for " + shown + ", but you typed " + typed);
  }

  function abandon(reason) {
    if (!run) return;
    stop();
    setVerdict(el.rightVerdict, "wait", reason);
    setVerdict(el.leftVerdict, "wait", "");
    delete document.body.dataset.running;
  }

  el.play.addEventListener("click", start);
  el.replay.addEventListener("click", start);
  el.seed.addEventListener("change", function () {
    abandon("Seed changed. Press Play.");
    el.rightTitle.textContent = "humaninput, seed " + el.seed.value;
    el.timelineSeed.textContent = el.seed.value;
  });
  el.fixed.addEventListener("change", function () {
    abandon(el.fixed.checked ? "Fix on. Press Play." : "Fix off. Press Play.");
  });
  // Hidden tabs throttle timers, which would change the timing being replayed.
  document.addEventListener("visibilitychange", function () {
    if (document.hidden) abandon("Stopped because the tab was hidden. Press Replay same seed.");
  });

  if (reducedMotion.matches) {
    var note = document.createElement("p");
    note.className = "keyboard-off";
    note.textContent = "Key animation is off because your system asks for reduced motion. The keys and results still appear.";
    el.keyboard.after(note);
  }
})();
